#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>

#define MAX_MELODIES 100
#define MAX_PHRASES 100
#define MAX_LEN 10000

int main() {
    int n, m;
    // Read number of melodies and phrases
    scanf("%d %d", &n, &m);

    // Store melody lengths
    int melody_len[MAX_MELODIES];
    for (int i = 0; i < n; i++) {
        scanf("%d", &melody_len[i]);
    }

    // Store phrase data: min_len, max_len, score
    int min_len[MAX_PHRASES], max_len[MAX_PHRASES], score[MAX_PHRASES];
    for (int i = 0; i < m; i++) {
        scanf("%d %d %d", &min_len[i], &max_len[i], &score[i]);
    }

    // For each melody, compute maximum score
    for (int mel = 0; mel < n; mel++) {
        int L = melody_len[mel];

        // DP array: dp[i] = max score to reach length i, -1 if impossible
        int dp[MAX_LEN + 1];
        for (int i = 0; i <= L; i++) {
            dp[i] = -1;
        }
        dp[0] = 0;

        // Unbounded knapsack: for each length, try each phrase
        for (int len = 0; len <= L; len++) {
            if (dp[len] == -1) continue;
            for (int p = 0; p < m; p++) {
                for (int k = min_len[p]; k <= max_len[p]; k++) {
                    int new_len = len + k;
                    if (new_len > L) break;
                    int new_score = dp[len] + score[p];
                    if (new_score > dp[new_len]) {
                        dp[new_len] = new_score;
                    }
                }
            }
        }

        printf("%d\n", dp[L]);
    }

    return 0;
}

