#define MAXL 100001
#define NEG_INF (-1000000000)

long long dp[MAXL], ndp[MAXL];
// sliding window max
int deq[MAXL];

int main() {
    int P;
    scanf("%d", &P);
    int lo[105], hi[105], sc[105];
    for (int i = 0; i < P; i++)
        scanf("%d %d %d", &lo[i], &hi[i], &sc[i]);

    int M;
    scanf("%d", &M);
    while (M--) {
        int L;
        scanf("%d", &L);
        for (int i = 0; i <= L; i++) dp[i] = NEG_INF;
        dp[0] = 0;

        // iterate, allow reuse of phrases
        // do multiple passes until stable? or just one pass with proper ordering
        // Actually we can use phrases multiple times, so standard unbounded knapsack
        // Process positions left to right
        for (int j = 0; j <= L; j++) {
            if (dp[j] == NEG_INF) continue;
            for (int p = 0; p < P; p++) {
                for (int l = lo[p]; l <= hi[p] && j + l <= L; l++) {
                    if (dp[j] + sc[p] > dp[j + l])
                        dp[j + l] = dp[j] + sc[p];
                }
            }
        }

        if (dp[L] == NEG_INF) printf("-1\n");
        else printf("%lld\n", dp[L]);
    }
    return 0;
