#include <stdio.h>
#include <stdlib.h>

typedef long long ll;

#define NEG_INF (-(1LL<<60))

typedef struct {
    int l, r;
    ll p;
} Phrase;

int main(void) {
    int N, M;
    if (scanf("%d %d", &N, &M) != 2) return 0;

    Phrase *phr = (Phrase *)malloc(sizeof(Phrase) * N);
    for (int i = 0; i < N; i++) {
        scanf("%d %d %lld", &phr[i].l, &phr[i].r, &phr[i].p);
    }

    int *mel = (int *)malloc(sizeof(int) * M);
    int maxX = 0;
    for (int i = 0; i < M; i++) {
        scanf("%d", &mel[i]);
        if (mel[i] > maxX) maxX = mel[i];
    }

    ll *dp = (ll *)malloc(sizeof(ll) * (maxX + 1));
    for (int i = 0; i <= maxX; i++) dp[i] = NEG_INF;
    dp[0] = 0;

    for (int x = 1; x <= maxX; x++) {
        ll best = NEG_INF;
        for (int i = 0; i < N; i++) {
            int L = phr[i].l;
            int R = phr[i].r;
            if (x < L) continue;

            int from = x - R;
            if (from < 0) from = 0;
            int to = x - L;

            ll local = NEG_INF;
            for (int k = from; k <= to; k++) {
                if (dp[k] > local) local = dp[k];
            }
            if (local != NEG_INF) {
                ll cand = local + phr[i].p;
                if (cand > best) best = cand;
            }
        }
        dp[x] = best;
    }

    for (int i = 0; i < M; i++) {
        if (dp[mel[i]] == NEG_INF) printf("-1\n");
        else printf("%lld\n", dp[mel[i]]);
    }

    free(phr);
    free(mel);
    free(dp);
    return 0;
}

