int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, m;
    cin >> n >> m;

    vector<int> melody_len(n);
    for (int i = 0; i < n; i++) {
        cin >> melody_len[i];
    }

    // Store phrases: (min_len, max_len, score)
    vector<tuple<int, int, int>> phrases(m);
    for (int i = 0; i < m; i++) {
        int a, b, s;
        cin >> a >> b >> s;
        phrases[i] = {a, b, s};
    }

    // For each melody length, compute max score
    for (int len : melody_len) {
        // DP: dp[i] = max score for total length i, -inf if impossible
        const int INF = -1e9;
        vector<int> dp(len + 1, INF);
        dp[0] = 0;

        // Unbounded knapsack: we can use any phrase any number of times
        for (int i = 0; i <= len; i++) {
            if (dp[i] == INF) continue;
            for (auto &[a, b, s] : phrases) {
                for (int use_len = a; use_len <= b; use_len++) {
                    int next = i + use_len;
                    if (next <= len) {
                        dp[next] = max(dp[next], dp[i] + s);
                    }
                }
            }
        }

        if (dp[len] < 0) {
            cout << -1 << '\n';
        } else {
            cout << dp[len] << '\n';
        }
    }

    return 0;
