int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, M;
    cin >> N >> M;

    vector<int> L(N), R(N), P(N);
    for (int i = 0; i < N; ++i) cin >> L[i] >> R[i] >> P[i];

    vector<int> W(M);
    int maxW = 0;
    for (int i = 0; i < M; ++i) {
        cin >> W[i];
        maxW = max(maxW, W[i]);
    }

    const long long NEG = -(1LL << 60);

    vector<long long> dp(maxW + 1, NEG), ndp(maxW + 1);
    dp[0] = 0;

    for (int i = 0; i < N; ++i) {
        fill(ndp.begin(), ndp.end(), NEG);

        deque<int> dq;
        for (int j = 0; j <= maxW; ++j) {
            int addIdx = j - L[i];
            if (addIdx >= 0 && dp[addIdx] != NEG) {
                while (!dq.empty() && dp[dq.back()] <= dp[addIdx]) dq.pop_back();
                dq.push_back(addIdx);
            }

            int removeLimit = j - R[i];
            while (!dq.empty() && dq.front() < removeLimit) dq.pop_front();

            ndp[j] = dp[j];
            if (!dq.empty()) {
                ndp[j] = max(ndp[j], dp[dq.front()] + P[i]);
            }
        }

        dp.swap(ndp);
    }

    for (int i = 0; i < M; ++i) {
        if (dp[W[i]] < 0) cout << -1 << '\n';
        else cout << dp[W[i]] << '\n';
    }

    return 0;
}

import java.util.*;
