public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        // Read number of phrase types
        int n = Integer.parseInt(br.readLine().trim());

        int[] minLen = new int[n];
        int[] maxLen = new int[n];
        int[] score = new int[n];

        for (int i = 0; i < n; i++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            minLen[i] = Integer.parseInt(st.nextToken());
            maxLen[i] = Integer.parseInt(st.nextToken());
            score[i] = Integer.parseInt(st.nextToken());
        }

        // Read number of melodies
        int m = Integer.parseInt(br.readLine().trim());
        int[] melodies = new int[m];
        for (int i = 0; i < m; i++) {
            melodies[i] = Integer.parseInt(br.readLine().trim());
        }

        // Preprocess: find maximum length among all phrases
        int maxTotalLen = 0;
        for (int len : melodies) {
            maxTotalLen = Math.max(maxTotalLen, len);
        }

        // DP array: dp[i] = max score for length i, -inf if impossible
        long[] dp = new long[maxTotalLen + 1];
        Arrays.fill(dp, Long.MIN_VALUE);
        dp[0] = 0;

        // Fill DP using unbounded knapsack approach
        for (int i = 1; i <= maxTotalLen; i++) {
            for (int j = 0; j < n; j++) {
                for (int k = minLen[j]; k <= maxLen[j] && k <= i; k++) {
                    if (dp[i - k] != Long.MIN_VALUE) {
                        dp[i] = Math.max(dp[i], dp[i - k] + score[j]);
                    }
                }
            }
        }

        // Output results for each melody
        StringBuilder sb = new StringBuilder();
        for (int len : melodies) {
            if (dp[len] == Long.MIN_VALUE) {
                sb.append("-1\n");
            } else {
                sb.append(dp[len]).append("\n");
            }
        }
        System.out.print(sb.toString());
    }
}

