import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Phrase {
        int l, r;
        long s;
        Phrase(int l, int r, long s) {
            this.l = l;
            this.r = r;
            this.s = s;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int n = fs.nextInt(); // number of phrases
        int q = fs.nextInt(); // number of melodies/questions

        Phrase[] phrases = new Phrase[n];
        int maxX = 0;
        for (int i = 0; i < n; i++) {
            int l = fs.nextInt();
            int r = fs.nextInt();
            long s = fs.nextLong();
            phrases[i] = new Phrase(l, r, s);
        }

        int[] queries = new int[q];
        for (int i = 0; i < q; i++) {
            queries[i] = fs.nextInt();
            maxX = Math.max(maxX, queries[i]);
        }

        long NEG = Long.MIN_VALUE / 4;
        long[] dp = new long[maxX + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;

        // Unbounded knapsack with interval lengths:
        // dp[x] = max over phrases i and len in [l_i, r_i] of dp[x-len] + s_i
        // Straightforward O(n * maxX * avgRange).
        // We optimize each phrase using sliding window maximum over dp.
        for (Phrase p : phrases) {
            long[] ndp = Arrays.copyOf(dp, dp.length);

            Deque<Integer> dq = new ArrayDeque<>();
            for (int x = p.l; x <= maxX; x++) {
                int addIdx = x - p.l;
                while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[addIdx]) dq.pollLast();
                dq.addLast(addIdx);

                int minIdx = x - p.r;
                while (!dq.isEmpty() && dq.peekFirst() < minIdx) dq.pollFirst();

                if (!dq.isEmpty() && dp[dq.peekFirst()] != NEG) {
                    ndp[x] = Math.max(ndp[x], dp[dq.peekFirst()] + p.s);
                }
            }

            // Since each phrase can be used multiple times, keep relaxing with same phrase.
            // Standard complete knapsack with interval lengths needs forward DP on same array.
            // So repeat using ndp as source in-place with sliding window over ndp itself.
            // Easier and correct way: process complete knapsack directly on one array.
            // Recompute properly below.
            dp = completeIntervalKnapsack(dp, p, maxX, NEG);
        }

        StringBuilder sb = new StringBuilder();
        for (int x : queries) {
            sb.append(dp[x] == NEG ? -1 : dp[x]).append('\n');
        }
        System.out.print(sb.toString());
    }

    static long[] completeIntervalKnapsack(long[] base, Phrase p, int maxX, long NEG) {
        long[] dp = Arrays.copyOf(base, base.length);

        // For complete knapsack with interval [l, r], transitions are:
        // dp[x] = max(dp[x], max_{k in [l,r]} dp[x-k] + s)
        // Since dp on RHS is the same array and x increases, this is valid.
        // We maintain a deque on current dp values.
        Deque<Integer> dq = new ArrayDeque<>();
        for (int x = p.l; x <= maxX; x++) {
            int addIdx = x - p.l;
            while (!dq.isEmpty() && dp[dq.peekLast()] <= dp[addIdx]) dq.pollLast();
            dq.addLast(addIdx);

            int minIdx = x - p.r;
            while (!dq.isEmpty() && dq.peekFirst() < minIdx) dq.pollFirst();

            if (!dq.isEmpty() && dp[dq.peekFirst()] != NEG) {
                dp[x] = Math.max(dp[x], dp[dq.peekFirst()] + p.s);
            }
        }
        return dp;
    }
}

